/**
 * Create a user record.
 *
 * Accepts either an options object or positional arguments:
 *
 *   makeUser({ id: 1, displayName: 'Alice' })
 *   makeUser({ id: 1, name: 'Alice' })
 *   makeUser(1, 'Alice')
 *
 * @param {object|string|number} input User data object, or the user id.
 * @param {string} [displayName] Display name when passing positional arguments.
 * @returns {{ id: string|number, displayName: string }} The user record.
 */
export function makeUser(input = {}, displayName) {
  const source =
    input !== null && typeof input === 'object'
      ? input
      : { id: input, displayName };

  const id = source.id;
  const name = source.displayName ?? source.name ?? '';

  return { id, displayName: name };
}

export default makeUser;

