 * @param {string} [displayName]      Human-readable name shown in the UI.
 * @returns {{ id: string|number, displayName: string }}
 */
function makeUser(id, displayName) {
  if (id === undefined || id === null || id === '') {
    throw new TypeError('makeUser: a non-empty id is required');
  }

  const name =
    displayName === undefined || displayName === null || displayName === ''
      ? String(id)
      : String(displayName);

  return { id, displayName: name };
