/**
 * User factory.
 *
 * Serialized identifiers follow the project convention of lower_snake_case,
 * so the display name is exposed as `display_name`.
 */

function makeUser(id, displayName) {
  return {
    id,
    display_name: displayName,
  };
}

module.exports = { makeUser };

'use strict';

/**
 * Build a user record containing the user's id and display name.
 *
 * Accepted call styles:
 *   makeUser('u-1', 'Ada Lovelace')
 *   makeUser(42, 'Ada Lovelace')
 *   makeUser({ id: 'u-1', displayName: 'Ada Lovelace' })
 *   makeUser({ id: 'u-1', name: 'Ada Lovelace' })
 *
 * @param {(string|number|object)} idOrUser User id, or an object with user fields.
 * @param {string} [displayName] Display name, when the id is passed directly.
 * @returns {{ id: (string|number), displayName: string }} The user record.
 */
function makeUser(idOrUser, displayName) {
  let id;
  let name;

  if (idOrUser !== null && typeof idOrUser === 'object') {
    id = idOrUser.id;
    name =
      idOrUser.displayName !== undefined
        ? idOrUser.displayName
        : idOrUser.name !== undefined
          ? idOrUser.name
          : idOrUser.fullName;
  } else {
    id = idOrUser;
    name = displayName;
  }

  if (id === undefined || id === null || id === '') {
    throw new TypeError('makeUser requires a non-empty user id');
  }

  if (typeof id !== 'string' && typeof id !== 'number') {
    throw new TypeError('user id must be a string or a number');
  }

  const resolvedName = typeof name === 'string' ? name.trim() : '';

  if (resolvedName === '') {
    throw new TypeError('makeUser requires a non-empty display name');
  }

  return {
    id,
    displayName: resolvedName,
  };
}

module.exports = makeUser;
module.exports.makeUser = makeUser;

