'use strict';

/**
 * Build a user record.
 *
 * Accepts either an existing user-like object (`{ id, displayName }` /
 * `{ id, display_name }`) or an explicit `(id, displayName)` pair, and returns
 * a plain object carrying the user's id and display name.
 *
 * @param {object|string|number} user - User source object, or the user id.
 * @param {string} [displayName] - Display name when passing a bare id.
 * @returns {{ id: (string|number), display_name: string }}
 */
function makeUser(user, displayName) {
  if (user !== null && typeof user === 'object') {
    const id = user.id;
    const name = user.display_name ?? user.displayName ?? '';
    return { id, display_name: name };
  }

  return { id: user, display_name: displayName ?? '' };
}

module.exports = { makeUser };

/**
 * Create a user object.
 *
 * @param {object} options
 * @param {string|number} options.id - The user's unique id.
 * @param {string} options.displayName - The user's display name.
 * @returns {{ id: string|number, displayName: string }} The user object.
 */
export function makeUser({ id, displayName }) {
  return { id, displayName };
}

export default makeUser;

/**
 * Create a user record.
 *
 * Accepts either an options object or positional arguments:
 *   makeUser({ id: 1, display_name: "Ada" })
 *   makeUser(1, "Ada")
 *
 * Returns an object containing the user's `id` and `display_name`.
 *
 * @param {object|string|number} input User fields, or the user's id.
 * @param {string} [maybeDisplayName] Display name when called positionally.
 * @returns {{ id: (string|number), display_name: string }}
 */
export function makeUser(input = {}, maybeDisplayName) {
  if (input === null || typeof input !== "object") {
    return {
      id: input,
      display_name: maybeDisplayName ?? String(input),
    };
  }

  const { id, display_name, displayName, name } = input;

  return {
    id,
    display_name: display_name ?? displayName ?? name ?? "",
  };
}

export default makeUser;

'use strict';

/**
 * Build a user object.
 *
 * @param {string|number} id - The user's unique identifier.
 * @param {string} [displayName] - The name shown in the UI. Falls back to the id.
 * @returns {{ id: string|number, displayName: string }}
 */
function makeUser(id, displayName) {
  if (id === undefined || id === null || id === '') {
    throw new TypeError('makeUser requires an id');
  }

  const name =
    typeof displayName === 'string' && displayName.trim() !== ''
      ? displayName.trim()
      : String(id);

  return {
    id,
    displayName: name,
  };
}

module.exports = { makeUser };
module.exports.makeUser = makeUser;
module.exports.default = makeUser;

/**
 * Create a user object with a stable id and a human-readable display name.
 *
 * Serialized identifiers use lower_snake_case, so the returned object exposes
 * the display name as `display_name`.
 *
 * @param {string|number} id - The user's unique id.
 * @param {string} displayName - The user's display name.
 * @returns {{ id: string|number, display_name: string }}
 */
export function makeUser(id, displayName) {
  if (id === undefined || id === null || id === '') {
    throw new TypeError('makeUser requires a non-empty id');
  }
  if (typeof displayName !== 'string' || displayName.trim() === '') {
    throw new TypeError('makeUser requires a non-empty displayName');
  }

  return {
    id,
    display_name: displayName.trim(),
  };
}

export default makeUser;
